const CHORALE_GROUP_BIN = '../chorale-search/build/chorale-group';

// Generated by `make corpus`.
const CORPUS_DIR = '../corpus/bach-370-chorales';

// The corpus is searched once more for each variant.
const GROUPING_TIMEOUT = 60_000;

const EXIT_CODE_ERRORS = {
    3: (message) => new ValidationError('The group query contains one or more validation errors', message),
    2: (message) => new InvalidArgumentError('The chorale-group tool received invalid command-line arguments', message),
};

// Takes a group query (see /docs/grouping) and answers with its tree of groups, also as a
// stream of progress events (see respondWithStream).
export default defineEventHandler(async (event) => {
    setResponseHeader(event, 'Content-Type', 'application/json');

    try {
        const body = await parseRequestBody(event);
        const group = ({ onEvent, signal } = {}) => {
            const args = [
                CORPUS_DIR,
                '--query', JSON.stringify(body),
            ];
            if (onEvent) args.push('--progress');

            return runCliTool({
                bin: CHORALE_GROUP_BIN,
                toolName: 'chorale-group',
                args,
                exitCodeErrors: EXIT_CODE_ERRORS,
                overflowHint: 'Narrow the query, or keep fewer groups with "maxGroupCount" or "minMatchCount"',
                timeout: GROUPING_TIMEOUT,
                onEvent,
                signal,
            });
        };
        const answer = ({ stdout, durationMs }) => ({ result: parseToolJsonOutput(stdout, 'chorale-group'), durationMs });

        if (acceptsStream(event)) {
            return respondWithStream(event, async (send, signal) => answer(await group({ onEvent: send, signal })));
        }
        return answer(await group());
    } catch (e) {
        return toErrorResponse(event, e);
    }
});
